def add_equipment_floor_drops(apps, schema_editor):

    Equipment = apps.get_model(
        "inventory",
        "Equipment",
    )

    FloorDropItem = apps.get_model(
        "battle",
        "FloorDropItem",
    )

    # ========================================================
    # 通常ランク装備
    # ========================================================

    for floor, ranks in FLOOR_RANKS.items():

        equipments = Equipment.objects.filter(
            rank__in=ranks,
        )

        for equipment in equipments:

            FloorDropItem.objects.update_or_create(
                floor=floor,
                item_id=equipment.item_id,
                defaults={
                    "drop_weight": 100,
                },
            )

    # ========================================================
    # 階層固有Sランク装備
    # ========================================================

    for floor, conditions in S_EQUIPMENT_DROPS.items():

        for slot, style in conditions:

            equipments = Equipment.objects.filter(
                rank="S",
                slot=slot,
                style=style,
            )

            for equipment in equipments:

                FloorDropItem.objects.update_or_create(
                    floor=floor,
                    item_id=equipment.item_id,
                    defaults={
                        "drop_weight": 100,
                    },
                )


